@Composable fun MiniPlayer(state: PlaybackState, vm: LibraryViewModel, open: () -> Unit) { val t=state.current ?: return; Column(Modifier.fillMaxWidth().background(MaterialTheme.colorScheme.surfaceVariant).clickable(onClick = open)) { LinearProgressIndicator(progress={ if(state.duration>0) state.position.toFloat()/state.duration else 0f },modifier=Modifier.fillMaxWidth().height(2.dp),color=MaterialTheme.colorScheme.onSurfaceVariant,trackColor=MaterialTheme.colorScheme.surfaceVariant); Row(Modifier.height(64.dp).padding(horizontal=12.dp),verticalAlignment=Alignment.CenterVertically){ Artwork(t,Modifier.size(42.dp));Column(Modifier.padding(start=11.dp).weight(1f)){Text(t.title,maxLines=1,overflow=TextOverflow.Ellipsis,fontWeight=FontWeight.SemiBold);Text(t.artist,maxLines=1,overflow=TextOverflow.Ellipsis,fontSize=12.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)};IconButton(onClick=vm.playback::toggle){Icon(if(state.isPlaying)Icons.Default.Pause else Icons.Default.PlayArrow,if(state.isPlaying)"Pause" else "Play")};IconButton(onClick=vm.playback::next){Icon(Icons.Default.SkipNext,"Next")}} } }
@Composable fun NowPlaying(state: PlaybackState, vm: LibraryViewModel, close: () -> Unit) { val t=state.current ?: return; val progress=if(state.duration>0) state.position.toFloat()/state.duration else 0f
    Column(Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background).systemBarsPadding().pointerInput(Unit){detectVerticalDragGestures { _,drag -> if(drag>50) close() }}.padding(horizontal=24.dp)) { Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){IconButton(onClick=close){Icon(Icons.Default.ArrowBack,"Close now playing")};Text("NOW PLAYING",modifier=Modifier.weight(1f),textAlign=TextAlign.Center,letterSpacing=2.sp,fontSize=12.sp,fontWeight=FontWeight.Bold);IconButton(onClick={}){Icon(Icons.Default.MoreVert,"More options")}}; Spacer(Modifier.weight(.18f)); Artwork(t,Modifier.fillMaxWidth().aspectRatio(1f));Spacer(Modifier.weight(.12f)); Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(t.title,maxLines=1,overflow=TextOverflow.Ellipsis,fontSize=27.sp,fontWeight=FontWeight.Bold,letterSpacing=(-.7).sp);Text(t.artist,maxLines=1,overflow=TextOverflow.Ellipsis,fontSize=17.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)};IconButton(onClick={vm.favorite(t)}){Icon(if(t.favorite)Icons.Default.Favorite else Icons.Default.FavoriteBorder,if(t.favorite)"Remove favorite" else "Favorite")}}; Spacer(Modifier.height(14.dp)); Slider(value=progress,onValueChange={ vm.playback.seek((it*state.duration).toLong()) },modifier=Modifier.fillMaxWidth(),colors=SliderDefaults.colors(thumbColor=MaterialTheme.colorScheme.onBackground,activeTrackColor=MaterialTheme.colorScheme.onBackground,inactiveTrackColor=MaterialTheme.colorScheme.surfaceVariant));Row(Modifier.fillMaxWidth()){Text(state.position.asTime(),fontSize=12.sp,color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.weight(1f));Text(state.duration.asTime(),fontSize=12.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)}; Spacer(Modifier.height(8.dp)); Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceEvenly,verticalAlignment=Alignment.CenterVertically){IconButton(onClick=vm.playback::shuffle){Icon(Icons.Default.Shuffle,"Shuffle",tint=if(state.shuffled)MaterialTheme.colorScheme.onBackground else MaterialTheme.colorScheme.onSurfaceVariant)};IconButton(onClick=vm.playback::previous,modifier=Modifier.size(62.dp)){Icon(Icons.Default.SkipPrevious,"Previous",modifier=Modifier.size(38.dp))};FilledIconButton(onClick=vm.playback::toggle,modifier=Modifier.size(76.dp),colors=IconButtonDefaults.filledIconButtonColors(containerColor=MaterialTheme.colorScheme.onBackground,contentColor=MaterialTheme.colorScheme.background)){Icon(if(state.isPlaying)Icons.Default.Pause else Icons.Default.PlayArrow,if(state.isPlaying)"Pause" else "Play",modifier=Modifier.size(43.dp))};IconButton(onClick=vm.playback::next,modifier=Modifier.size(62.dp)){Icon(Icons.Default.SkipNext,"Next",modifier=Modifier.size(38.dp))};IconButton(onClick=vm.playback::cycleRepeat){Icon(if(state.repeatMode==1)Icons.Default.RepeatOne else Icons.Default.Repeat,"Repeat",tint=if(state.repeatMode==0)MaterialTheme.colorScheme.onSurfaceVariant else MaterialTheme.colorScheme.onBackground)}};Spacer(Modifier.weight(.15f)); Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceEvenly){TextButton(onClick={}){Icon(Icons.Default.QueueMusic,"Queue");Spacer(Modifier.width(6.dp));Text("Queue")};TextButton(onClick={}){Icon(Icons.Default.Timer,"Sleep timer");Spacer(Modifier.width(6.dp));Text("Sleep")}};Spacer(Modifier.height(16.dp)) }
}
@Composable fun SearchScreen(tracks: List<Track>, vm: LibraryViewModel, close:()->Unit) { var query by androidx.compose.runtime.remember { androidx.compose.runtime.mutableStateOf("") }; val filtered=tracks.filter { query.isBlank() || listOf(it.title,it.artist,it.album).any { v->v.contains(query,true) } }; Column { Row(Modifier.padding(16.dp),verticalAlignment=Alignment.CenterVertically){IconButton(onClick=close){Icon(Icons.Default.ArrowBack,"Close search")};OutlinedTextField(value=query,onValueChange={query=it},placeholder={Text("Search songs, artists, albums")},singleLine=true,modifier=Modifier.weight(1f))};LazyColumn { itemsIndexed(filtered,key={_,t->t.id}){i,t->TrackRow(t,{vm.play(filtered,i)},{vm.favorite(t)})} } } }
@Composable fun Empty(title:String,body:String) = Column(Modifier.fillMaxWidth().padding(48.dp),horizontalAlignment=Alignment.CenterHorizontally){Icon(Icons.Default.LibraryMusic,null,modifier=Modifier.size(46.dp),tint=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(18.dp));Text(title,fontSize=20.sp,fontWeight=FontWeight.Bold);Spacer(Modifier.height(8.dp));Text(body,color=MaterialTheme.colorScheme.onSurfaceVariant,textAlign=TextAlign.Center)}
